    private ArcanaUnleashedPtBr(){}
    private static void p(String canonical,String pt){PT.put(canonical,pt);}
    public static String display(String value){if(value==null)return "";for(Map.Entry<String,String> e:PT.entrySet()){if(norm(e.getKey()).equals(norm(value))||norm(e.getValue()).equals(norm(value)))return e.getValue();}return value;}
    public static String canonical(String value){if(value==null)return "";for(Map.Entry<String,String> e:PT.entrySet()){if(norm(e.getKey()).equals(norm(value))||norm(e.getValue()).equals(norm(value)))return e.getKey();}return value;}
    public static boolean same(String a,String b){return norm(canonical(a)).equals(norm(canonical(b)));}
    private static String norm(String s){String x=Normalizer.normalize(s==null?"":s.toLowerCase(new Locale("pt","BR")),Normalizer.Form.NFD).replaceAll("\\p{M}+","");return x.replaceAll("[^a-z0-9]+"," ").trim();}
